/**
 * Single source of truth for the party blocks that appear inside the LOI.
 *
 * `OZYNTEL_PARTY` is the "Company B" side of every LOI generated by this
 * app. The signer's organisation (Company A) is collected on the signing
 * form (see `LOISignModal`) and passed through to `renderLoiText`.
 *
 * If any field below is genuinely not known yet, we use a clearly-marked
 * "TBD — …" string. We never leave raw bracket placeholders like
 * `[Address]` in either the preview or the generated PDF.
 */

export interface PartyInfo {
  /** Full legal name as it should appear on the LOI. */
  legalName: string;
  /** Country / jurisdiction of incorporation. */
  jurisdiction: string;
  /** Registered address (street, city, postal code, country). */
  registeredAddress: string;
  /** Optional company registration number (KvK in NL, Companies House in UK, etc.). */
  registrationNumber?: string;
  /** Optional public-facing contact email. */
  contactEmail?: string;
  /** Optional public-facing website. */
  website?: string;
}

/**
 * Ozyntel — fills the Company B side of every LOI.
 *
 * NOTE — the exact registered address and KvK number aren't fixed yet, so
 * those two fields use explicit "TBD — …" strings. They will not leak as
 * raw bracket placeholders in either the UI or the PDF.
 */
export const OZYNTEL_PARTY: PartyInfo = {
  legalName: "Ozyntel B.V.",
  jurisdiction: "The Netherlands",
  registeredAddress: "TBD — Ozyntel registered address (provided on definitive agreement)",
  registrationNumber: "TBD — Ozyntel KvK registration",
  contactEmail: "hello@ozyntel.com",
  website: "https://ozyntel.com",
};

/** Default governing-law jurisdiction when none is collected on the form. */
export const DEFAULT_GOVERNING_LAW = "The Netherlands";

/** Default court jurisdiction. */
export const DEFAULT_COURT_JURISDICTION = "Amsterdam, The Netherlands";

/**
 * Render a one-line legal description of a party for use inside the LOI
 * "Parties" section. Falls back to "TBD — provided on definitive agreement"
 * for any missing field, so no raw [brackets] reach the user.
 */
export function describeParty(party: Partial<PartyInfo>): {
  legalName: string;
  jurisdiction: string;
  registeredAddress: string;
} {
  return {
    legalName: party.legalName?.trim() || "TBD — provided on definitive agreement",
    jurisdiction: party.jurisdiction?.trim() || "TBD — provided on definitive agreement",
    registeredAddress:
      party.registeredAddress?.trim() || "TBD — provided on definitive agreement",
  };
}
